Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -29,4 +29,26 @@
 </section>
 <footer class="footer"><span><strong>Objetivo:</strong> colete moedas e derrote o Oni.</span><span class="controls-note"><b>J</b> espada&nbsp; <b>K</b> teleporte&nbsp; <b>ESPAÇO</b> saltar</span></footer>
 </main>
 <script>
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const W=960,H=540,GROUND=454,LEVEL=3400;
+const ui={overlay:document.getElementById('overlay'),title:document.getElementById('overlayTitle'),text:document.getElementById('overlayText'),eyebrow:document.getElementById('eyebrow'),start:document.getElementById('startBtn'),hearts:document.getElementById('hearts'),coins:document.getElementById('coins'),stage:document.getElementById('stage'),progress:document.getElementById('progress'),bossbar:document.getElementById('bossbar'),bossHealth:document.getElementById('bossHealth'),toast:document.getElementById('toast')};
+let mode='menu',last=0,camera=0,muted=true,audioCtx=null,toastTimer=0;
+const keys={left:false,right:false};
+let player,coins,enemies,boss,particles,worldTime=0,coinCount=0;
+function resetGame(){player={x:90,y:GROUND-52,w:34,h:52,vx:0,vy:0,face:1,hp:5,inv:0,attack:0,attackCD:0,teleCD:0,teleFx:0,ground:true,walk:0};coinCount=0;coins=[];enemies=[];particles=[];camera=0;worldTime=0;
+  [310,485,735,965,1190,1420,1680,1900,2160,2410,2640,2870].forEach((x,i)=>coins.push({x,y:GROUND-(i%3===1?112:64),taken:false,phase:i}));
+  [{x:570,type:'ninja',hp:2},{x:850,type:'oni',hp:2},{x:1110,type:'ninja',hp:2},{x:1370,type:'oni',hp:2},{x:1640,type:'ninja',hp:2},{x:1930,type:'oni',hp:2},{x:2200,type:'ninja',hp:2},{x:2500,type:'oni',hp:2},{x:2770,type:'ninja',hp:2}].forEach(e=>enemies.push({...e,y:GROUND-45,w:e.type==='oni'?39:31,h:45,alive:true,dir:-1,stun:0,hitCD:0,phase:Math.random()*5}));
+  boss={x:3160,y:GROUND-83,w:62,h:83,hp:7,maxHp:7,alive:true,mode:'idle',timer:1.2,dir:-1,hitCD:0,phase:0};
+  syncHud();}
+function startGame(){resetGame();mode='playing';ui.overlay.classList.add('hidden');ui.bossbar.classList.remove('show');last=performance.now();}
+function showOverlay(kind){mode=kind;ui.overlay.classList.remove('hidden');if(kind==='pause'){ui.eyebrow.textContent='Respire, guerreiro';ui.title.textContent='Jogo pausado';ui.text.textContent='A floresta espera por você. Retome sua jornada quando estiver pronto.';ui.start.textContent='CONTINUAR';}else if(kind==='dead'){ui.eyebrow.textContent='A sombra venceu... por enquanto';ui.title.textContent='Fim de jogo';ui.text.textContent=`Você reuniu ${coinCount} moedas. Recupere suas forças e tente novamente!`;ui.start.textContent='TENTAR NOVAMENTE';}else if(kind==='win'){ui.eyebrow.textContent='A honra do clã está salva';ui.title.textContent='Lenda das sombras';ui.text.textContent=`O Oni foi derrotado! Você recolheu ${coinCount} moedas e libertou a floresta. Um verdadeiro guerreiro ninja.`;ui.start.textContent='JOGAR DE NOVO';}}
+function syncHud(){ui.hearts.innerHTML=Array.from({length:5},(_,i)=>`<span class="heart ${i>=player.hp?'empty':''}">${i<player.hp?'♥':'♥'}</span>`).join('');ui.coins.textContent=String(coinCount).padStart(2,'0');ui.progress.style.width=`${Math.min(100,player.x/LEVEL*100)}%`;if(player.x>LEVEL-530)ui.stage.textContent='CHEFÃO · TEMPLO ONI';else if(player.x>1600)ui.stage.textContent='FASE 1 · VALE SOMBRIO';else ui.stage.textContent='FASE 1 · FLORESTA';ui.bossbar.classList.toggle('show',player.x>LEVEL-630&&boss.alive);ui.bossHealth.style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;}
+function sound(freq=440,duration=.08,type='sine'){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
+function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:(Math.random()-.7)*180,life:.35+Math.random()*.38,max:.73,color,size:2+Math.random()*4});}
+function hurt(amount=1){if(player.inv>0||mode!=='playing')return;player.hp=Math.max(0,player.hp-amount);player.inv=1.15;burst(player.x+player.w/2,player.y+22,'#ff7381',12);sound(115,.2,'sawtooth');syncHud();if(player.hp<=0)showOverlay('dead');}
+function attack(){if(mode!=='playing'||player.attackCD>0)return;player.attack=.25;player.attackCD=.37;sound(310,.09,'sawtooth');const reach=92,center=player.x+player.w/2+player.face*55;
+  for(const e of enemies){if(!e.alive)continue;const dx=e.x+e.w/2-center;if(Math.abs(dx)<reach*.58&&Math.abs((e.y+e.h)-(player.y+player.h))<67&&Math.sign(dx||player.face)===player.face){e.hp--;e.stun=.38;e.x+=player.face*22;burst(e.x+e.w/2,e.y+20,'#ffc06c',6);sound(170,.06,'square');if(e.hp<=0){e.alive=false;burst(e.x+e.w/2,e.y+22,'#b67dff',15);}}}
+  if(boss.alive&&Math.abs((boss.x+boss.w/2)-center)<70&&Math.abs((boss.y+boss.h)-(player.y+player.h))<92){if(boss.hitCD<=0){boss.hp--;boss.hitCD=.28;boss.mode='stun';boss.timer=.24;burst(boss.x+boss.w/2,boss.y+27,'#ffd176',12);sound(125,.12,'square');if(boss.hp<=0){boss.alive=false;burst(boss.x+boss.w/2,boss.y+35,'#ffc966',40);syncHud();}}}
+}
+function teleport(){if(mode!=='playing'||player.teleCD>0)return;const from=player.x+player.w/2;player.x=Math.min(LEVEL-40,Math.max(20,player.x+player.face*178));player.teleCD=2.4;player.teleFx=.45;player.inv=Math.max(player.inv,.28);burst(from,player.y+player.h/2,'#9b8cff',13);burst(player.x+player.w/2,player.y+player.h/2,'#b0a5ff',13);sound(720,.12,'sine');}

