function teleport(){if(mode!=='playing'||player.teleCD>0)return;const from=player.x+player.w/2;player.x=Math.min(LEVEL-40,Math.max(20,player.x+player.face*178));player.teleCD=2.4;player.teleFx=.45;player.inv=Math.max(player.inv,.28);burst(from,player.y+player.h/2,'#9b8cff',13);burst(player.x+player.w/2,player.y+player.h/2,'#b0a5ff',13);sound(720,.12,'sine');}
function update(dt){if(mode!=='playing')return;worldTime+=dt;player.inv=Math.max(0,player.inv-dt);player.attack=Math.max(0,player.attack-dt);player.attackCD=Math.max(0,player.attackCD-dt);player.teleCD=Math.max(0,player.teleCD-dt);player.teleFx=Math.max(0,player.teleFx-dt);
  const dir=(keys.right?1:0)-(keys.left?1:0);player.vx=dir*235;if(dir)player.face=dir;player.x=Math.max(8,Math.min(LEVEL-28,player.x+player.vx*dt));player.walk+=Math.abs(player.vx)*dt*.045;
  player.vy+=1450*dt;player.y+=player.vy*dt;if(player.y+player.h>=GROUND){player.y=GROUND-player.h;player.vy=0;player.ground=true;}else player.ground=false;
  for(const c of coins){if(c.taken)continue;if(Math.hypot(player.x+17-c.x,player.y+24-c.y)<35){c.taken=true;coinCount++;sound(760,.1,'sine');burst(c.x,c.y,'#ffdb75',8);syncHud();}}
  for(const e of enemies){if(!e.alive)continue;e.stun=Math.max(0,e.stun-dt);e.hitCD=Math.max(0,e.hitCD-dt);if(e.stun<=0){const dx=player.x-e.x;if(Math.abs(dx)<340){e.dir=Math.sign(dx)||e.dir;e.x+=e.dir*(e.type==='oni'?60:82)*dt;}}if(Math.abs(player.x-e.x)<34&&Math.abs(player.y-e.y)<44&&e.hitCD<=0){e.hitCD=.92;hurt();} }
  if(boss.alive){boss.hitCD=Math.max(0,boss.hitCD-dt);boss.phase+=dt;if(boss.mode==='stun'){boss.timer-=dt;if(boss.timer<=0)boss.mode='idle';}else if(boss.mode==='idle'){boss.timer-=dt;if(boss.timer<=0){boss.mode='tell';boss.timer=.65;boss.dir=Math.sign(player.x-boss.x)||-1;}}else if(boss.mode==='tell'){boss.timer-=dt;if(boss.timer<=0){boss.mode='charge';boss.timer=.52;boss.dir=Math.sign(player.x-boss.x)||boss.dir;}}else if(boss.mode==='charge'){boss.x+=boss.dir*350*dt;boss.timer-=dt;if(Math.abs(player.x-boss.x)<55&&boss.hitCD<=0){boss.hitCD=.8;hurt();}if(boss.timer<=0||boss.x<LEVEL-480||boss.x>LEVEL-50){boss.mode='recover';boss.timer=.8;}}else if(boss.mode==='recover'){boss.timer-=dt;if(boss.timer<=0)boss.mode='idle';}if(Math.abs(player.x-boss.x)<48&&boss.hitCD<=0&&boss.mode!=='tell'){boss.hitCD=.85;hurt();}}
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=260*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);camera=Math.max(0,Math.min(LEVEL-W,player.x-W*.36));syncHud();if(!boss.alive)showOverlay('win');}
function poly(points,fill,stroke=null,lw=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}}
function rr(x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();}
function drawBackground(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1c2943');g.addColorStop(.52,'#68495f');g.addColorStop(1,'#ed9a76');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  const moonX=760-camera*.08;ctx.save();ctx.globalAlpha=.92;ctx.fillStyle='#ffe2ab';ctx.beginPath();ctx.arc(moonX,119,42,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.22;ctx.beginPath();ctx.arc(moonX,119,58,0,Math.PI*2);ctx.fill();ctx.restore();
  // distant mountain silhouettes
  for(let i=0;i<6;i++){let x=i*230-(camera*.13%230)-100;poly([[x,355],[x+105,205+(i%2)*30],[x+206,355]],i%2?'#3b3b58':'#41405f');poly([[x+75,248+(i%2)*30],[x+105,205+(i%2)*30],[x+138,253+(i%2)*30],[x+119,245+(i%2)*30],[x+105,254+(i%2)*30],[x+91,244+(i%2)*30]],'#d6b8ad');}
  // distant pagoda
  let px=470-camera*.28;drawPagoda(px,304,.72,'#393348');let px2=1040-camera*.28;drawPagoda(px2,330,.52,'#49394c');
  // dark pine trees and lantern silhouettes
  for(let i=0;i<11;i++){let x=i*145-(camera*.36%145)-40;const h=95+(i%4)*19;ctx.fillStyle='#302c43';ctx.fillRect(x+32,358-h*.25,9,h*.4);for(let n=0;n<3;n++)poly([[x+36,340-h+n*28],[x+2,368-h+n*28],[x+70,368-h+n*28]],n%2?'#35324b':'#302d46');}
  // floating petals
  for(let i=0;i<28;i++){const x=((i*137+worldTime*(18+i%4)*10-camera*.18)%(W+40))-20,y=70+(i*67%280)+Math.sin(worldTime*1.3+i)*8;ctx.save();ctx.translate(x,y);ctx.rotate(worldTime+i);ctx.fillStyle=i%2?'#ffb8bb90':'#ffe0ce90';ctx.beginPath();ctx.ellipse(0,0,3.8,2,0,0,Math.PI*2);ctx.fill();ctx.restore();}
  const groundGrad=ctx.createLinearGradient(0,GROUND,0,H);groundGrad.addColorStop(0,'#554047');groundGrad.addColorStop(.12,'#342c3c');groundGrad.addColorStop(1,'#151c2a');ctx.fillStyle=groundGrad;ctx.fillRect(0,GROUND,W,H-GROUND);ctx.fillStyle='#f0a36f';ctx.fillRect(0,GROUND,W,3);ctx.fillStyle='#ffcb8860';ctx.fillRect(0,GROUND+4,W,2);
  // ground stones and grass blades
  for(let i=0;i<35;i++){let x=(i*67-camera*.8)%(W+50);if(x<0)x+=W+50;ctx.fillStyle=i%3?'#a16a6150':'#edaa7760';ctx.fillRect(x,GROUND+18+(i*17%55),12+(i%4)*4,2);if(i%3===0){ctx.strokeStyle='#6b805c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,GROUND+2);ctx.lineTo(x-3,GROUND-7);ctx.moveTo(x+2,GROUND+2);ctx.lineTo(x+7,GROUND-6);ctx.stroke();}}
}
function drawPagoda(x,base,s,color){ctx.save();ctx.translate(x,base);ctx.scale(s,s);ctx.fillStyle=color;ctx.fillRect(-28,-88,56,88);ctx.fillRect(-40,-99,80,10);ctx.fillRect(-34,-101,68,4);ctx.fillRect(-22,-137,44,39);poly([[-51,-137],[0,-160],[51,-137]],color);ctx.fillRect(-48,-137,96,5);ctx.fillRect(-17,-177,34,41);poly([[-42,-177],[0,-196],[42,-177]],color);ctx.fillRect(-38,-177,76,4);ctx.fillRect(-10,-210,20,34);poly([[-24,-210],[0,-222],[24,-210]],color);ctx.fillRect(-2,-239,4,30);ctx.restore();}

