document.getElementById('soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♫':'♪';e.currentTarget.title=muted?'Som desligado':'Som ligado';if(!muted)sound(660,.1);});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')keys.left=true;if(k==='d'||k==='arrowright')keys.right=true;if((k===' '||k==='w'||k==='arrowup')&&!e.repeat&&mode==='playing'&&player.ground){player.vy=-570;player.ground=false;sound(440,.07);}if((k==='j'||k==='z')&&!e.repeat)attack();if((k==='k'||k==='x')&&!e.repeat)teleport();if(k==='escape'||k==='p'){if(mode==='playing'||mode==='pause')togglePause();}});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')keys.left=false;if(k==='d'||k==='arrowright')keys.right=false;});window.addEventListener('blur',()=>{keys.left=keys.right=false;if(mode==='playing')togglePause();});
document.querySelectorAll('[data-hold]').forEach(btn=>{const hold=btn.dataset.hold;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[hold]=true;btn.classList.add('pressed');btn.setPointerCapture?.(e.pointerId);});const release=e=>{keys[hold]=false;btn.classList.remove('pressed');};btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release);});
document.querySelectorAll('[data-action]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.classList.add('pressed');if(btn.dataset.action==='attack')attack();if(btn.dataset.action==='teleport')teleport();if(btn.dataset.action==='jump'&&mode==='playing'&&player.ground){player.vy=-570;player.ground=false;sound(440,.07);}btn.setPointerCapture?.(e.pointerId);});const release=()=>btn.classList.remove('pressed');btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release);});
function frame(now){const dt=Math.min(.034,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame);}
resetGame();requestAnimationFrame(frame);
</script>
</body>
